INSERT INTO scholarship_sources (id, author, title, publication, year, bib_core, dedup_key, raw_example) VALUES (2, 'John H. Walton', 'The Lost World of Genesis One', 'IVP Academic, 2009', 2009, 'John H. Walton, The Lost World of Genesis One (IVP Academic, 2009)', '2009 academic genesis ivp john lost one walton world', 'John H. Walton, *The Lost World of Genesis One* (IVP Academic, 2009), pp. 55-71, on ancient cosmic geography');
